import { RenderStepType } from '../static/Enums'
import { COORDS_MAX_X, COORDS_MAX_Y, DEFAULT_LINE_WIDTH } from 'static/constants/Index'
import CanvasWindow from './CanvasWindow'
import RenderItemLine from './RenderItemLine'
import RenderItemRectangle from './RenderItemRectangle'
import RenderItemArc from './RenderItemArc'
import RenderItemGroup from './RenderItemGroup'
import RenderItemBase from './interfaces/RenderItemBase'
import Point from './Point'
import { DefaultRenderer } from '../render/DefaultRenderer'
import RenderItemText from './RenderItemText'
import AnimationData from '../AnimationData'
import ButtonOptions from './ButtonOptions'
import Animations from '../Animations'

export default class RenderItem {
    isAnimate: boolean = false

    isTemp: boolean = false

    isDebug: boolean = false

    isContextMenu: boolean = false

    showTooltip: boolean = false

    showContextMenu: boolean = false

    get hasTooltip() {
        return this.tooltipTemplate && this.tooltipTemplate.length > 0
    }

    get hasContextMenu() {
        return this.contextMenuItems.length > 0
    }

    get isInitializing() {
        return this.animation.isInitializing
    }

    // todo: remove ?
    type: RenderStepType

    color: string

    animation: AnimationData = AnimationData.default

    activeColor: string

    stroke: string

    activeStroke: string

    tooltipTemplate: string

    contextMenuItems: ButtonOptions[] = []

    layer: number = 0

    onClick: () => void

    line: RenderItemLine

    rect: RenderItemRectangle

    arc: RenderItemArc

    text: RenderItemText

    group: RenderItemGroup

    // todo: group to RenderItemAnimationItem ?
    startTimer: DOMHighResTimeStamp | null

    // todo: group to RenderItemAnimationItem ?
    mouseLeave: boolean

    private items(): RenderItemBase[] {
        return [this.line, this.rect, this.arc, this.text, this.group]
    }

    render(ctx: CanvasRenderingContext2D, window: CanvasWindow) {
        this.updateInit()

        if (this.animation.init <= 0) {
            return
        }

        this.adjust(window)

        ctx.beginPath()

        ctx.lineWidth = DEFAULT_LINE_WIDTH
        ctx.setLineDash([])

        ctx.fillStyle = this.activeColor
        ctx.strokeStyle = this.activeStroke ?? this.activeColor

        for (const item of this.items()) {
            item?.render(ctx, window, this)
            if (item)
                return
        }
    }

    animate(point: Point) {
        if (!this.isAnimate || this.isInitializing) {
            return
        }

        for (const item of this.items()) {
            if (item) {
                this.continueAnimate(point, item)
                return
            }
        }
    }

    tooltip(point: Point) {
        if (!this.hasTooltip || this.isInitializing) {
            return
        }

        for (const item of this.items()) {
            if (item) {
                this.continueTooltip(point, item)
                return
            }
        }
    }

    contextMenu(point: Point) {
        // if (!this.hasContextMenu) {
        //     return
        // }

        if (this.isInitializing) {
            return
        }

        for (const item of this.items()) {
            if (item) {
                this.continueContextMenu(point, item)
                return
            }
        }
    }

    in(point: Point) {
        for (const item of this.items()) {
            if (item) {
                return item.isMouseOver(point)
            }
        }

        return false
    }

    private adjust(window: CanvasWindow): void {
        for (const item of this.items()) {
            item?.adjust(window)
            if (item)
                return
        }
    }

    /**
     * Updates init animation progress, removes it when finished
     */
    private updateInit() {
        const animation = this.animation

        if (!animation.isInitializing) {
            return
        }

        animation.initStart ??= DefaultRenderer.timer

        const passed = DefaultRenderer.timer - animation.initStart - animation.initDelay
        const progress = Math.min(Math.max(passed / animation.initDuration, 0), 1)

        animation.init = Animations.getTransition(progress)

        if (progress == 1) {
            animation.init = 1
            animation.initDuration = 0
        }
    }

    private continueAnimate(point: Point, item: RenderItemBase) {
        if (item.isMouseOver(point)) {
            if (this.mouseLeave) {
                this.mouseLeave = false
            }

            item.animate(this, false, point)
        } else if (this.startTimer) {
            if (!this.mouseLeave && DefaultRenderer.timer - this.startTimer > 450) {
                this.startTimer = null
            }
            this.mouseLeave = true

            item.animate(this, true, point)

            if (this.startTimer && DefaultRenderer.timer - this.startTimer > 450) {
                this.mouseLeave = false
                this.startTimer = null
            }
        }
    }

    // todo: remove "item" argument ?
    private continueTooltip(point: Point, item: RenderItemBase) {
        if (item.isMouseOver(point)) {
            this.showTooltip = item.tooltip(this, point)
        } else if (this.startTimer && !this.mouseLeave) {
            this.mouseLeave = true

            this.showTooltip = item.tooltip(this, point)
        } else {
            this.showTooltip = false
        }
    }

    // todo: remove "item" argument ?
    private continueContextMenu(point: Point, item: RenderItemBase) {
        if (item.isMouseOver(point)) {
            this.showContextMenu = item.contextMenu(this, point)
        } else if (this.startTimer && !this.mouseLeave) {
            this.mouseLeave = true

            this.showContextMenu = item.contextMenu(this, point)
        } else {
            this.showContextMenu = false
        }
    }

    static adjustX(window: CanvasWindow, x: number) {
        return Math.round(x / COORDS_MAX_X * window.width + window.x)
    }

    static adjustY(window: CanvasWindow, y: number) {
        return Math.round(y / COORDS_MAX_Y * window.height + window.y)
    }

    static reAdjustX(window: CanvasWindow, x: number): number {
        return ((x - window.x) * COORDS_MAX_X) / window.width
    }

    static reAdjustY(window: CanvasWindow, y: number): number {
        return ((y - window.y) * COORDS_MAX_Y) / window.height
    }
}